package com.friendoncampus.credit.config;
import java.net.URI;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.core.annotation.Order;import org.springframework.http.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import tools.jackson.databind.ObjectMapper;
@Configuration public class InternalSecurityConfiguration {@Bean @Order(1)SecurityFilterChain internalCredits(HttpSecurity h,@Value("${app.service-auth.trusted-keys:{}}")String trust,ObjectMapper m)throws Exception{return h.securityMatcher("/internal/**").csrf(AbstractHttpConfigurer::disable).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.GET,"/internal/credits/orders/*/evidence").authenticated().anyRequest().denyAll()).oauth2ResourceServer(o->o.authenticationEntryPoint((q,r,e)->problem(r,q,m)).jwt(j->j.decoder(new ServiceTokenDecoder("credit-service",trust)::decode))).build();}private static void problem(jakarta.servlet.http.HttpServletResponse r,jakarta.servlet.http.HttpServletRequest q,ObjectMapper m)throws java.io.IOException{r.setStatus(401);r.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);var p=ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,"A valid service assertion is required");p.setInstance(URI.create(q.getRequestURI()));m.writeValue(r.getOutputStream(),p);}}
